// refreshCookies.js
// refresh-cookies.js
import puppeteer from "puppeteer";
import fs from "fs";
import path from "path";
import dotenv from "dotenv";

dotenv.config();

const COOKIES_PATH = path.resolve(process.cwd(), "cookies.txt");
const LOGIN_URL = "https://accounts.google.com/ServiceLogin?service=youtube";

// Credentials from .env
const YOUTUBE_EMAIL = process.env.GOOGLE_EMAIL;
const YOUTUBE_PASSWORD = process.env.GOOGLE_PASSWORD;

if (!YOUTUBE_EMAIL || !YOUTUBE_PASSWORD) {
  console.error("❌ Missing GOOGLE_EMAIL or GOOGLE_PASSWORD in .env");
  process.exit(1);
}

async function exportCookiesToNetscapeFormat(cookies) {
  let output = "# Netscape HTTP Cookie File\n# Generated by refresh-cookies-server.mjs\n\n";

  for (const cookie of cookies) {
    const domain = cookie.domain.startsWith(".") ? cookie.domain : "." + cookie.domain;
    const flag = cookie.hostOnly ? "FALSE" : "TRUE";
    const pathVal = cookie.path;
    const secure = cookie.secure ? "TRUE" : "FALSE";
    const expiration = cookie.expires ? Math.floor(new Date(cookie.expires).getTime() / 1000) : 2147483647;
    const name = cookie.name;
    const value = cookie.value;

    output += [domain, flag, pathVal, secure, expiration, name, value].join("\t") + "\n";
  }

  return output;
}

export async function refreshCookies() {
  console.log("🌐 Launching Chrome to refresh YouTube cookies...");

  const browser = await puppeteer.launch({
    headless: false, // Important: use real GUI with Xvfb
    executablePath: "/usr/bin/google-chrome-stable", // Chrome path on Ubuntu
    args: [
      "--no-sandbox",
      "--disable-setuid-sandbox",
      "--disable-dev-shm-usage",
      "--disable-blink-features=AutomationControlled"
    ],
  });

  const page = await browser.newPage();

  await page.setUserAgent(
    "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 " +
    "(KHTML, like Gecko) Chrome/115.0.0.0 Safari/537.36"
  );
  await page.setViewport({ width: 1366, height: 768 });

  await page.goto(LOGIN_URL, { waitUntil: "networkidle2" });

  console.log("🔹 Logging in with credentials...");

  await page.type("input[type='email']", YOUTUBE_EMAIL, { delay: 100 });
  await page.click("#identifierNext");
  await page.waitForTimeout(3000);

  await page.waitForSelector("input[type='password']", { visible: true });
  await page.type("input[type='password']", YOUTUBE_PASSWORD, { delay: 100 });
  await page.click("#passwordNext");

  // Wait for YouTube home page (or login completion)
  await page.waitForNavigation({ waitUntil: "networkidle2", timeout: 60000 });

  console.log("✅ Login successful, saving cookies...");

  const cookies = await page.cookies();
  const netscapeCookies = await exportCookiesToNetscapeFormat(cookies);

  fs.writeFileSync(COOKIES_PATH, netscapeCookies);
  console.log(`🍪 Cookies saved to ${COOKIES_PATH}`);

  await browser.close();
}

// Run manually
if (process.argv[1] === new URL(import.meta.url).pathname) {
  (async () => {
    try {
      await refreshCookies();
      console.log("🎉 Cookies refreshed successfully!");
    } catch (err) {
      console.error("❌ Error refreshing cookies:", err);
    }
  })();
}
